use vstd::prelude::*;

// Verus does not natively verify floating-point properties extensively,
// so we focus on the logical structure and reflect the required properties explicitly.

// Function: imag
// Given an array (Vec) of pairs of f64 representing complex numbers (real, imag),
// returns a Vec<f64> containing the imaginary parts in order.

fn imag(val: Vec<(f64, f64)>) -> Vec<f64> {
    // The length of the output equals length of input.
    // For each index i, output[i] = val[i].1 (imag part).
    // We will build the result iteratively using an invariant.

    let n = val.len();

    // We use a while loop with an invariant to build the output vector step-by-step.
    let mut i: usize = 0;
    let mut res: Vec<f64> = Vec::new();

    // Invariant:
    // - res.len() == i
    // - For all j in 0..i, res[j] == val[j].1
    // - i <= n
    // - For all j in 0..i,
    //      if val[j].1 == 0.0 then res[j] == 0.0
    //      if val[j] != (0.0, 0.0) then res[j] == val[j].1
    while i < n {
        let imag_part = val[i].1;
        res.push(imag_part);

        // Assertions reflecting specifications:
        // if imag part is 0.0 then output is exactly 0.0
        assert!(if imag_part == 0.0 { res[i] == 0.0 } else { true });
        // if val[i] != zero complex number, then output equals imag_part
        assert!(if val[i].0 != 0.0 || val[i].1 != 0.0 {
            res[i] == imag_part
        } else {
            true
        });

        i += 1;
    }

    // After loop, length matches
    assert!(res.len() == n);
    // For all indices, output equals imag part from input
    let mut idx: usize = 0;
    while idx < n {
        assert!(res[idx] == val[idx].1);
        idx += 1;
    }

    res
}